{
  "status": "SUPPORTED",
  "task_summary": "Set up two refreshment stations and position the remote for easy access.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_setting",
        "entity_kind": "OBJECT",
        "function": "A surface prepared with food or drink for a person.",
        "required_count": 2,
        "binding_policy": "DISTINCT",
        "candidate_categories": ["table", "sideboard", "desk"],
        "required_properties": ["flat", "stable", "holds_objects"]
      },
      {
        "id": "refreshment_item",
        "entity_kind": "OBJECT",
        "function": "A container of food or drink provided to a person.",
        "required_count": 2,
        "binding_policy": "REUSABLE",
        "candidate_categories": ["cup", "plate", "bowl", "snack_package"],
        "required_properties": ["holds_consumables"]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "A device used to operate the television.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["remote_control", "speaker", "switch"],
        "required_properties": ["operates_tv"]
      },
      {
        "id": "accessible_surface",
        "entity_kind": "REGION",
        "function": "A location within reach of the seated viewers.",
        "required_count": 1,
        "binding_policy": "SHARED",
        "candidate_categories": ["table_top", "shelf", "armrest"],
        "required_properties": ["flat", "reachable"]
      }
    ],
    "functional_relations": [
      {
        "id": "item_on_setting",
        "relation": "is_on",
        "participant_roles": ["refreshment_item", "refreshment_setting"],
        "required": true
      },
      {
        "id": "control_on_surface",
        "relation": "is_on",
        "participant_roles": ["entertainment_control", "accessible_surface"],
        "required": true
      }
    ],
    "operation_pairings": [
